def transform(grid):
    """Convert the non-5 color to 0 and recolor 5 with that other color."""
    colors = {value for row in grid for value in row}
    other = next((value for value in colors if value != 5), 0)
    return [[other if value == 5 else 0 for value in row] for row in grid]

